            tl_pos.setdefault(color, set()).add((r, c))
tl_colors = {3: 4, 6: 1, 1: 6, 4: 3}
for color, out_c in tl_colors.items():
    for (r, c) in tl_pos[color]:
        output[r][c] = out_c

# TR: Input colors 5→4→8, Output 8→4→5
tr_pos = {}
for r in range(4, 10):
    for c in range(12, 18):
        color = input_rows[r][c]
        if color in [5, 4, 8]:
            tr_pos.setdefault(color, set()).add((r, c))
tr_colors = {5: 8, 4: 4, 8: 5}
for color, out_c in tr_colors.items():
    for (r, c) in tr_pos[color]:
        output[r][c] = out_c

# Bottom: Input 6→8→2→4→3, Output 3→4→2→8→6
bot_pos = {}
for r in range(11, 20):
    for c in range(2, 18):
        color = input_rows[r][c]
        if color in [6, 8, 2, 4, 3]:
            bot_pos.setdefault(color, set()).add((r, c))
bot_colors = {6: 3, 8: 4, 2: 2, 4: 8, 3: 6}
for color, out_c in bot_colors.items():
    for (r, c) in bot_pos[color]:
        output[r][c] = out_c

# Print full grid
print("=== Full Output Grid ===")
for r in range(20):
    row_str = " ".join(str(output[r][c]) for c in range(19))
    print(f"r{r}: {row_str}")

# Format as JSON
